export const getAdminDeliveriesUrl = (params?: AdminDeliveriesParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/v1/notify/admin/deliveries?${stringifiedParams}`
    : `/api/v1/notify/admin/deliveries`;
};

export const adminDeliveries = async (
  params?: AdminDeliveriesParams,
  options?: RequestInit,
): Promise<AdminDeliveries200> => {
  return http<AdminDeliveries200>(getAdminDeliveriesUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getAdminDeliveriesQueryKey = (params?: AdminDeliveriesParams) => {
  return [`/api/v1/notify/admin/deliveries`, ...(params ? [params] : [])] as const;
};

export const getAdminDeliveriesQueryOptions = <
  TData = Awaited<ReturnType<typeof adminDeliveries>>,
  TError = unknown,
>(
  params?: AdminDeliveriesParams,
  options?: {
    query?: Partial<UseQueryOptions<Awaited<ReturnType<typeof adminDeliveries>>, TError, TData>>;
    request?: SecondParameter<typeof http>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getAdminDeliveriesQueryKey(params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof adminDeliveries>>> = ({ signal }) =>
    adminDeliveries(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof adminDeliveries>>,
    TError,
    TData
  > & { queryKey: DataTag<QueryKey, TData, TError> };
};

